const mongoose = require('mongoose');

/** Low-stock and expiry alerts generated by the scheduled stock job. */
const alertSchema = new mongoose.Schema(
  {
    pharmacy: { type: mongoose.Schema.Types.ObjectId, ref: 'Pharmacy', required: true, index: true },
    catalogItem: { type: mongoose.Schema.Types.ObjectId, ref: 'CatalogItem', required: true },
    batch: { type: mongoose.Schema.Types.ObjectId, ref: 'InventoryBatch' },
    type: { type: String, enum: ['LowStock', 'NearExpiry', 'Expired'], required: true },
    message: { type: String, required: true },
    resolved: { type: Boolean, default: false },
    resolvedAt: Date,
  },
  { timestamps: true }
);

// at most one open alert of each type per item/batch
alertSchema.index(
  { catalogItem: 1, batch: 1, type: 1 },
  { unique: true, partialFilterExpression: { resolved: false } }
);

module.exports = mongoose.model('Alert', alertSchema);
